// Container image listings: listImages2 behind wrangler containers images list, run as shipped in cli.js
const fs = require("fs");
function symptom(m){console.error("FAIL: "+m);process.exit(1);}
function broken(m){console.error("ERROR: "+m);process.exit(2);}
(async()=>{
const src = fs.readFileSync("/w/node_modules/wrangler/wrangler-dist/cli.js","utf8");
const a = src.indexOf("async function listImages2(responses, digests = false, json2 = false)");
if (a<0) broken("listImages2 not found");
const b = src.indexOf("\n}\n", a);
if (b<0) broken("end of listImages2 not found");
const fn = src.slice(a, b+3);
let pre = "";
if (fn.includes("isValidImageTag2")) {
  const m = src.indexOf("function isValidImageTag2(value)");
  const p = src.match(/\n\s*imageTagPattern = ("[^"\n]*");\n/);
  const r = src.match(/\n\s*(imageTagRegexp = new RegExp\([^\n]*\);)\n/);
  if (m<0 || !p || !r) broken("shipped isValidImageTag2 or its regex not found");
  pre = "let imageTagPattern = "+p[1]+";\nlet "+r[1]+"\n" + src.slice(m, src.indexOf("\n}\n", m)+3);
}
const out=[];
const logger2={log:(s)=>out.push(String(s))};
const run = new Function("logger2", pre+fn+"\nreturn listImages2;")(logger2);
await run([{name:"one",tags:["hundred","sha256-release","sha256:239a0dfhasdfui235"]}], false, true);
let res;
try{res=JSON.parse(out.join("\n"));}catch(e){broken("bad output "+out.join("\n"));}
const tags=(res[0]&&res[0].tags)||[];
if(!tags.includes("hundred")) broken("missing hundred");
if(tags.includes("sha256:239a0dfhasdfui235")) broken("digest entry shown");
if(!tags.includes("sha256-release")) symptom("valid tag sha256-release is hidden from the image listing");
console.log("OK");
})().catch(e=>broken(String(e)));

